// ============================================
//  BIRTHDAY WEBSITE - script.js
// ============================================

const PHOTO_DATA = "data:image/jpeg;base64,";

// ---- Set photos ----
document.addEventListener('DOMContentLoaded', () => {
  document.getElementById('birthdayPhoto').src = PHOTO_DATA;
  document.getElementById('galleryPhoto1').src = PHOTO_DATA;
  document.getElementById('galleryPhoto2').src = PHOTO_DATA;
  document.getElementById('galleryPhoto3').src = PHOTO_DATA;
  initSparkles();
  initHearts();
  initFlowerRain();
  initCarouselDots();
});

// ============================================
//  FLOWER RAIN
// ============================================
const flowerCanvas = document.getElementById('flowerCanvas');
const fCtx = flowerCanvas.getContext('2d');
let flowers = [];
let flowerIntensity = 1;

function resizeFlowerCanvas() {
  flowerCanvas.width = window.innerWidth;
  flowerCanvas.height = window.innerHeight;
}
resizeFlowerCanvas();
window.addEventListener('resize', resizeFlowerCanvas);

const FLOWER_EMOJIS = ['🌸','🌹','🌺','🌼','🌻','💮','🪷','🌷','✿','❀'];
const COLORS = ['#FFB6C1','#FF69B4','#FF1493','#C2185B','#FFD700','#E8D5F5','#FFFFFF','#FFEAA0','#F48FB1'];

function createFlower() {
  return {
    x: Math.random() * flowerCanvas.width,
    y: -40,
    size: 14 + Math.random() * 22,
    speedY: 0.8 + Math.random() * 2.2,
    speedX: (Math.random() - 0.5) * 1.2,
    rotation: Math.random() * 360,
    rotSpeed: (Math.random() - 0.5) * 3,
    opacity: 0.6 + Math.random() * 0.4,
    emoji: FLOWER_EMOJIS[Math.floor(Math.random() * FLOWER_EMOJIS.length)],
    wind: (Math.random() - 0.5) * 0.4,
    wobble: Math.random() * Math.PI * 2,
    wobbleSpeed: 0.02 + Math.random() * 0.03,
    useEmoji: Math.random() > 0.3
  };
}

function spawnFlowers() {
  const target = Math.floor(60 * flowerIntensity);
  while (flowers.length < target) flowers.push(createFlower());
}

function drawFlowers() {
  fCtx.clearRect(0, 0, flowerCanvas.width, flowerCanvas.height);
  spawnFlowers();

  flowers.forEach((f, i) => {
    f.wobble += f.wobbleSpeed;
    f.x += f.speedX + Math.sin(f.wobble) * 0.6 + f.wind;
    f.y += f.speedY;
    f.rotation += f.rotSpeed;

    if (f.y > flowerCanvas.height + 60 || f.x < -60 || f.x > flowerCanvas.width + 60) {
      flowers[i] = createFlower();
      return;
    }

    fCtx.save();
    fCtx.globalAlpha = f.opacity;
    fCtx.translate(f.x, f.y);
    fCtx.rotate(f.rotation * Math.PI / 180);

    if (f.useEmoji) {
      fCtx.font = f.size + 'px serif';
      fCtx.textAlign = 'center';
      fCtx.textBaseline = 'middle';
      fCtx.fillText(f.emoji, 0, 0);
    } else {
      // Simple petal shape
      const color = COLORS[Math.floor(Math.random() * COLORS.length)];
      fCtx.beginPath();
      fCtx.ellipse(0, 0, f.size * 0.4, f.size * 0.7, 0, 0, Math.PI * 2);
      fCtx.fillStyle = color;
      fCtx.fill();
    }

    fCtx.restore();
  });

  requestAnimationFrame(drawFlowers);
}
drawFlowers();

// ============================================
//  CONFETTI
// ============================================
const confettiCanvas = document.getElementById('confettiCanvas');
const cCtx = confettiCanvas.getContext('2d');
let confettiPieces = [];
let confettiActive = false;

function resizeConfetti() {
  confettiCanvas.width = window.innerWidth;
  confettiCanvas.height = window.innerHeight;
}
resizeConfetti();
window.addEventListener('resize', resizeConfetti);

function launchConfetti() {
  confettiActive = true;
  for (let i = 0; i < 200; i++) {
    confettiPieces.push({
      x: Math.random() * confettiCanvas.width,
      y: Math.random() * confettiCanvas.height - confettiCanvas.height,
      w: 8 + Math.random() * 10,
      h: 4 + Math.random() * 6,
      color: COLORS[Math.floor(Math.random() * COLORS.length)],
      rot: Math.random() * 360,
      rotS: (Math.random() - 0.5) * 8,
      vx: (Math.random() - 0.5) * 4,
      vy: 2 + Math.random() * 4,
      life: 1
    });
  }
  animateConfetti();
}

function animateConfetti() {
  if (!confettiActive) return;
  cCtx.clearRect(0, 0, confettiCanvas.width, confettiCanvas.height);
  confettiPieces = confettiPieces.filter(p => p.y < confettiCanvas.height + 20 && p.life > 0);

  confettiPieces.forEach(p => {
    p.x += p.vx;
    p.y += p.vy;
    p.rot += p.rotS;
    p.life -= 0.003;
    cCtx.save();
    cCtx.globalAlpha = Math.min(p.life, 1);
    cCtx.translate(p.x, p.y);
    cCtx.rotate(p.rot * Math.PI / 180);
    cCtx.fillStyle = p.color;
    cCtx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
    cCtx.restore();
  });

  if (confettiPieces.length > 0) requestAnimationFrame(animateConfetti);
  else { confettiActive = false; cCtx.clearRect(0, 0, confettiCanvas.width, confettiCanvas.height); }
}

// ============================================
//  SPARKLES
// ============================================
function initSparkles() {
  const container = document.getElementById('sparkleContainer');
  for (let i = 0; i < 40; i++) {
    const s = document.createElement('div');
    s.className = 'sparkle';
    s.style.cssText = `
      left: ${Math.random()*100}%;
      top: ${Math.random()*100}%;
      width: ${4+Math.random()*8}px;
      height: ${4+Math.random()*8}px;
      animation-delay: ${Math.random()*3}s;
      animation-duration: ${1.5+Math.random()*2}s;
      background: ${Math.random()>0.5?'#FFD700':'#FFB6C1'};
      box-shadow: 0 0 8px 3px ${Math.random()>0.5?'#FFD700':'#FFB6C1'};
    `;
    container.appendChild(s);
  }
}

// ============================================
//  FLOATING HEARTS
// ============================================
function initHearts() {
  const container = document.getElementById('heartsContainer');
  const emojis = ['❤️','💕','💖','💗','💝','🌹'];
  setInterval(() => {
    const h = document.createElement('div');
    h.className = 'floating-heart';
    h.textContent = emojis[Math.floor(Math.random() * emojis.length)];
    h.style.cssText = `
      left: ${Math.random()*100}%;
      font-size: ${0.8+Math.random()*1.8}rem;
      animation-duration: ${6+Math.random()*8}s;
      animation-delay: 0s;
    `;
    container.appendChild(h);
    setTimeout(() => h.remove(), 14000);
  }, 1200);
}

// ============================================
//  OPEN SURPRISE
// ============================================
let surpriseOpened = false;

function openSurprise() {
  if (surpriseOpened) return;
  surpriseOpened = true;

  document.getElementById('surpriseBtn').disabled = true;
  document.getElementById('surpriseBtn').style.opacity = '0.6';

  // Boost flower rain
  flowerIntensity = 3;
  for (let i = 0; i < 60; i++) flowers.push(createFlower());

  // Confetti
  launchConfetti();
  setTimeout(launchConfetti, 1200);
  setTimeout(launchConfetti, 2400);

  // Show surprise section
  const surpriseSection = document.getElementById('surpriseSection');
  surpriseSection.classList.remove('hidden');

  // Scroll down
  setTimeout(() => surpriseSection.scrollIntoView({ behavior: 'smooth', block: 'start' }), 400);

  // Typewriter
  setTimeout(() => startTypewriter(), 1200);

  // Countdown
  setTimeout(() => startCountdown(), 16000);
}

// ============================================
//  TYPEWRITER
// ============================================
const BIRTHDAY_MESSAGE = `Happy Birthday, my dear friend. ❤️

On your special day, I want you to know how much you are appreciated and cherished. Your kindness, beautiful heart, and wonderful spirit make the world a brighter place. May this new year of your life bring you endless happiness, good health, success, and all the love you deserve.

Keep smiling, keep shining, and never stop being the amazing woman you are. I'm grateful to have you in my life. Enjoy every moment of your day, beautiful. 🎂🎉💐❤️

Happy Birthday, dear. May your heart be as full of joy today as you make others feel every day. ✨💕`;

function startTypewriter() {
  const el = document.getElementById('typewriterText');
  let i = 0;
  const speed = 28;
  el.textContent = '';

  function type() {
    if (i < BIRTHDAY_MESSAGE.length) {
      el.textContent += BIRTHDAY_MESSAGE[i++];
      setTimeout(type, speed);
    }
  }
  type();
}

// ============================================
//  CAROUSEL
// ============================================
let currentSlide = 0;
const slides = document.querySelectorAll('.carousel-slide');

function initCarouselDots() {
  const dotsContainer = document.getElementById('carouselDots');
  slides.forEach((_, i) => {
    const dot = document.createElement('div');
    dot.className = 'dot' + (i === 0 ? ' active' : '');
    dot.onclick = () => goToSlide(i);
    dotsContainer.appendChild(dot);
  });
  setInterval(() => nextSlide(), 4500);
}

function updateSlides() {
  slides.forEach((s, i) => s.classList.toggle('active', i === currentSlide));
  document.querySelectorAll('.dot').forEach((d, i) => d.classList.toggle('active', i === currentSlide));
}

function nextSlide() {
  currentSlide = (currentSlide + 1) % slides.length;
  updateSlides();
}
function prevSlide() {
  currentSlide = (currentSlide - 1 + slides.length) % slides.length;
  updateSlides();
}
function goToSlide(i) {
  currentSlide = i;
  updateSlides();
}

// ============================================
//  COUNTDOWN
// ============================================
function startCountdown() {
  const wrapper = document.getElementById('countdownWrapper');
  const numEl = document.getElementById('countdownNum');
  const ending = document.getElementById('endingSection');

  ending.scrollIntoView({ behavior: 'smooth', block: 'center' });

  let count = 3;
  numEl.textContent = count;

  const interval = setInterval(() => {
    count--;
    if (count > 0) {
      numEl.style.animation = 'none';
      numEl.offsetHeight; // reflow
      numEl.style.animation = 'countPulse 1s ease-in-out';
      numEl.textContent = count;
    } else {
      clearInterval(interval);
      wrapper.style.opacity = '0';
      setTimeout(() => {
        wrapper.style.display = 'none';
        document.getElementById('finalReveal').classList.remove('hidden');

        // Grand finale
        flowerIntensity = 6;
        for (let i = 0; i < 120; i++) flowers.push(createFlower());
        launchConfetti();
        setTimeout(launchConfetti, 600);
        setTimeout(launchConfetti, 1200);
        setTimeout(launchConfetti, 2000);
      }, 500);
    }
  }, 1000);
}
